`.trim();
}

function buildActivityEvidence(
  history: ChatMessage[],
  todayMemory: MisakiTodayMemory
): ActivityEvidence {
  return {
    texts: [
      ...history
        .filter(
          (item) =>
            item.role === "misaki"
        )
        .slice(-20)
        .map(
          (item) => item.text
        ),
      ...todayMemory.items,
    ],
  };
}

