+    { role: "model" as const, text: "そうなんだ、もう少し詳しく聞いてもいい？" },
+    { role: "user" as const, text: "今日は忙しかった" },
+    { role: "model" as const, text: "今日もお疲れさま。ゆっくり休んでね。" },
+    { role: "user" as const, text: "前にもこの話をしたね" },
+    { role: "model" as const, text: "その話、前にもしてくれたよね。覚えてるよ。" },
